// A programmable four-bit pattern detector.
//
// The pattern is an input, not a constant, so there is no table to
// precompute: the last four bits are kept in a shift register and
// compared with it. `fill` is there to stop the register matching
// before four real bits have arrived.

module seq_match (
    input  logic       clk,
    input  logic       rst_n,     // synchronous, active low
    input  logic       din,       // one bit per clock
    input  logic [3:0] pattern,   // held steady; pattern[3] arrives first
    output logic       found      // registered: high for one cycle on a match
);

    logic [3:0] hist;    // the last four bits; hist[3] is the oldest
    logic [2:0] fill;    // bits received since reset, saturating at 4

    // What the shift register will hold after this edge.
    wire [3:0] next_hist = {hist[2:0], din};

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            hist  <= 4'b0;
            fill  <= 3'd0;
            found <= 1'b0;
        end else begin
            hist  <= next_hist;
            if (fill != 3'd4) fill <= fill + 3'd1;
            // Three bits already in, plus the one arriving now.
            found <= (fill >= 3'd3) && (next_hist == pattern);
        end
    end

endmodule

// A saturating counter. It counts `inc` pulses and stops at its
// maximum rather than wrapping round to zero.

module det_counter #(
    parameter int W = 4
) (
    input  logic         clk,
    input  logic         rst_n,   // synchronous, active low
    input  logic         inc,     // count this cycle
    output logic [W-1:0] count,
    output logic         sat      // high exactly when count is at its maximum
);

    // your code here -- one register and one comparison. `sat` is a
    // function of `count`, so it is high the moment the count reaches
    // its maximum and not a cycle later.

    assign count = '0;
    assign sat   = 1'b0;

endmodule

// The top of milestone 2: the detector feeding the counter.
//
// There is no logic to write here. seq_match.sv and det_counter.sv are
// beside this file and are compiled with it; instantiate them.

module seq_detect #(
    parameter int W = 4
) (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         din,
    input  logic [3:0]   pattern,
    output logic         found,
    output logic [W-1:0] count,
    output logic         sat
);

    // your code here -- one seq_match and one det_counter, wired so
    // that every detection is one count. Pass W through to the counter.

    assign found = 1'b0;
    assign count = '0;
    assign sat   = 1'b0;

endmodule

payload.testbench:
`timescale 1ns/1ps

// The sample testbench for milestone 2. Submit uses another one, with a
// narrower counter so that saturation actually happens.
module tb;

  localparam int W = 4;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic rst_n = 1'b1;
  logic din   = 1'b0;
  logic found;
  logic [W-1:0] count;
  logic sat;

  logic [3:0] pattern = 4'b1011;

  seq_detect #(.W(W)) dut (
    .clk(clk), .rst_n(rst_n), .din(din), .pattern(pattern),
    .found(found), .count(count), .sat(sat)
  );

  integer i;

  task tick(input logic b);
    begin
      @(negedge clk); din = b;
      @(posedge clk); #1;
    end
  endtask

  task reset;
    begin
      @(negedge clk); rst_n = 1'b0; din = 1'b0;
      @(posedge clk); #1;
      rst_n = 1'b1;
    end
  endtask

  task stream(input integer n, input [31:0] bits);
    begin
      for (i = n - 1; i >= 0; i = i - 1) tick(bits[i]);
    end
  endtask

  logic [W-1:0] c_after_reset, c_one, c_overlap;
  logic sat_early;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    reset();
    c_after_reset = count;
    sat_early = sat;

    // One occurrence. The counter is registered, so the edge after the
    // pulse is the one that moves it.
    stream(4, 4'b1011);
    tick(1'b0);
    c_one = count;

    // 1011011 is two occurrences sharing a bit.
    reset();
    stream(7, 7'b1011011);
    tick(1'b0);
    c_overlap = count;

    $display("CHECK count_zero_after_reset 0 %0d AT %0d", c_after_reset, $time);
    $display("CHECK not_saturated_at_zero 0 %0d AT %0d", sat_early, $time);
    $display("CHECK counts_one_match 1 %0d AT %0d", c_one, $time);
    $display("CHECK counts_overlap_twice 2 %0d AT %0d", c_overlap, $time);
    $display("DONE 4");
    $finish;
  end

endmodule
